3	/**
4	 * Raised when a create-owner request arrives after the maximum number of owners (100) have already
5	 * been created today, counted by {@code registrationDate}. Checked so it appears in a
6	 * {@code throws} clause and can be routed to its escalation handler, which responds 429 Too Many
7	 * Requests.
8	 */
9	public class DailyOwnerLimitException extends Exception {
10	
11	    private final int count;
12	
13	    public DailyOwnerLimitException(int count) {
14	        super("Daily owner creation limit reached: " + count);
15	        this.count = count;
16	    }
17	
18	    /** The number of owners already created today. */
19	    public int getCount() {
20	        return this.count;
21	    }
22	}
